from itertools import permutations

def find_all_interval_series(n):
    solutions = []
    for perm in permutations(range(n)):
        diffs = [abs(perm[i] - perm[i+1]) for i in range(n-1)]
        if sorted(diffs) == list(range(1, n)):
            solutions.append(list(perm))
    return solutions

solutions = find_all_interval_series(4)
print(f"Found {len(solutions)} solutions:")
for sol in solutions:
    diffs = [abs(sol[i] - sol[i+1]) for i in range(3)]
    print(f"  {sol} -> differences: {diffs}")
